    public override object parseWsTrade(object trade, object market = null)
    {
        //
        //     {
        //         "buy_order_id": 1211625836466176,
        //         "amount_str": "1.08000000",
        //         "timestamp": "1584642064",
        //         "microtimestamp": "1584642064685000",
        //         "id": 108637852,
        //         "amount": 1.08,
        //         "sell_order_id": 1211625840754689,
        //         "price_str": "6294.77",
        //         "type": 1,
        //         "price": 6294.77
        //     }
        //
        Int64? microtimestamp = this.safeInteger(trade, "microtimestamp", 0);
        string? id = this.safeString(trade, "id");
        Int64? timestamp = this.parseToInt(divide(microtimestamp, 1000));
        string? price = this.safeString(trade, "price");
        string? amount = this.safeString(trade, "amount");
        if (isTrue(isEqual(market, null)))
        {
            market = this.safeMarket(null, market);
        }
        object symbol = getValue(market, "symbol");
        Int64? sideRaw = this.safeInteger(trade, "type");
        string side = ((bool) isTrue((isEqual(sideRaw, 0)))) ? "buy" : "sell";
        return this.safeTrade(new Dictionary<string, object>() {
            { "info", trade },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "symbol", symbol },
            { "id", id },
            { "order", null },
            { "type", null },
            { "takerOrMaker", null },
            { "side", side },
            { "price", price },
            { "amount", amount },
            { "cost", null },
            { "fee", null },
        }, market);
    }

    public virtual void handleTrade(WebSocketClient client, object message)
    {
        //
        //     {
        //         "data": {
        //             "buy_order_id": 1207733769326592,
        //             "amount_str": "0.14406384",
        //             "timestamp": "1583691851",
        //             "microtimestamp": "1583691851934000",
        //             "id": 106833903,
        //             "amount": 0.14406384,
        //             "sell_order_id": 1207733765476352,
        //             "price_str": "8302.92",
        //             "type": 0,
        //             "price": 8302.92
        //         },
        //         "event": "trade",
        //         "channel": "live_trades_btcusd"
        //     }
        //
        // the trade streams push raw trade information in real-time
        // each trade has a unique buyer and seller
        string? channel = this.safeString(message, "channel");
        if (isTrue(isEqual(channel, null)))
        {
            return;
        }
        List<object> parts = ((string)channel).Split(new [] {((string)"_")}, StringSplitOptions.None).ToList<object>();
        string? marketId = this.safeString(parts, 2);
        Dictionary<string, object> market = this.safeMarket(marketId);
        object symbol = getValue(market, "symbol");
        string messageHash = add("trades:", symbol);
        object data = this.safeValue(message, "data");
        object trade = this.parseWsTrade(data, market);
        object tradesArray = this.safeValue(this.trades, symbol);
        if (isTrue(isEqual(tradesArray, null)))
        {
            Int64? limit = this.safeInteger(this.options, "tradesLimit", 1000);
            tradesArray = new ArrayCache(limit);
            ((IDictionary<string,object>)this.trades)[(string)symbol] = tradesArray;
        }
        callDynamically(tradesArray, "append", new object[] {trade});
        callDynamically(client as WebSocketClient, "resolve", new object[] {tradesArray, messageHash});
    }

